import{_ as d,o as a,c as t,ag as o}from"./chunks/framework.DaCm-iTo.js";const h=JSON.parse('{"title":"Commands","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/codex/commands.md","filePath":"en/modules/codex/commands.md","lastUpdated":null}'),n={name:"en/modules/codex/commands.md"};function s(c,e,r,i,l,m){return a(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h1><p>EmakiCodex uses <code>/codex</code> as its main command and <code>/ecodex</code> as an alias. Documentation examples use <code>/codex</code>.</p><p>The Paper command entry itself requires <code>emakicodex.use</code>; administrative subcommands then check the matching reload, debug, or admin permission.</p><h2 id="command-list" tabindex="-1">Command list <a class="header-anchor" href="#command-list" aria-label="Permalink to &quot;Command list&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/codex</code></td><td><code>emakicodex.use</code></td><td>Shows help.</td></tr><tr><td><code>/codex help</code></td><td><code>emakicodex.use</code></td><td>Shows help.</td></tr><tr><td><code>/codex reload</code></td><td><code>emakicodex.reload</code> or <code>emakicodex.admin</code></td><td>Reloads config, language files, and advancement pages, re-registers advancements, and tries to resync online players.</td></tr><tr><td><code>/codex grant &lt;player&gt; &lt;advId&gt;</code></td><td><code>emakicodex.admin</code></td><td>Grants one Codex node to an online player.</td></tr><tr><td><code>/codex revoke &lt;player&gt; &lt;advId&gt;</code></td><td><code>emakicodex.admin</code></td><td>Revokes one Codex node from an online player.</td></tr><tr><td><code>/codex debug ...</code></td><td><code>emakicodex.debug</code> or <code>emakicodex.admin</code></td><td>Manages the <code>advancement</code> debug module. Detailed subcommands are provided by CoreLib DebugCommand.</td></tr></tbody></table><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/codex</span></span>
<span class="line"><span>/codex help</span></span>
<span class="line"><span>/codex reload</span></span>
<span class="line"><span>/codex grant Steve example/first_step</span></span>
<span class="line"><span>/codex grant Steve emakicodex:example/challenge</span></span>
<span class="line"><span>/codex revoke Steve example/first_step</span></span>
<span class="line"><span>/codex debug advancement on</span></span>
<span class="line"><span>/codex debug advancement off</span></span></code></pre></div><p><code>grant</code> and <code>revoke</code> require the target player to be online because the current implementation matches online player names exactly. <code>advId</code> supports two forms:</p><table tabindex="0"><thead><tr><th>Form</th><th>Example</th><th>Description</th></tr></thead><tbody><tr><td><code>page/node</code></td><td><code>example/first_step</code></td><td>Recommended short form for server administrators.</td></tr><tr><td>Full NamespacedKey</td><td><code>emakicodex:example/first_step</code></td><td>Matches the underlying vanilla advancement key.</td></tr></tbody></table><h2 id="reload-behavior" tabindex="-1">Reload behavior <a class="header-anchor" href="#reload-behavior" aria-label="Permalink to &quot;Reload behavior&quot;">​</a></h2><p><code>/codex reload</code> performs these operations:</p><ol><li>Releases missing default resources, controlled by <code>config.yml &gt; release_default_data</code>.</li><li>Reloads <code>config.yml</code>, <code>lang/*.yml</code>, and <code>advancements/*.yml</code>.</li><li>Removes and re-registers dynamic advancements under the EmakiCodex namespace.</li><li>If PacketEvents is available, re-pushes the tree to online players; otherwise online players may need to reconnect to see UI changes.</li></ol><h2 id="permission-nodes" tabindex="-1">Permission nodes <a class="header-anchor" href="#permission-nodes" aria-label="Permalink to &quot;Permission nodes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Covers</th></tr></thead><tbody><tr><td><code>emakicodex.use</code></td><td><code>true</code></td><td>Use the <code>/codex</code> command entry and help.</td></tr><tr><td><code>emakicodex.reload</code></td><td><code>op</code></td><td>Use <code>/codex reload</code>. Can be replaced by <code>emakicodex.admin</code>.</td></tr><tr><td><code>emakicodex.debug</code></td><td><code>op</code></td><td>Use <code>/codex debug ...</code>. Can be replaced by <code>emakicodex.admin</code>.</td></tr><tr><td><code>emakicodex.admin</code></td><td><code>op</code></td><td>Use grant/revoke admin commands and act as reload/debug override.</td></tr></tbody></table><p>Common LuckPerms examples:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/lp group default permission set emakicodex.use true</span></span>
<span class="line"><span>/lp group admin permission set emakicodex.admin true</span></span>
<span class="line"><span>/lp group admin permission set emakicodex.reload true</span></span>
<span class="line"><span>/lp group admin permission set emakicodex.debug true</span></span></code></pre></div><h2 id="common-failure-cases" tabindex="-1">Common failure cases <a class="header-anchor" href="#common-failure-cases" aria-label="Permalink to &quot;Common failure cases&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Case</th><th>Explanation</th></tr></thead><tbody><tr><td><code>Player not found</code></td><td>The <code>grant</code> / <code>revoke</code> target is offline, or the name is not an exact match.</td></tr><tr><td><code>Advancement ... is not registered or unchanged</code></td><td>The advancement ID is wrong, the page failed to load, or the player&#39;s progress did not change.</td></tr><tr><td>Online players cannot see new nodes after reload</td><td>PacketEvents is missing or resync failed; players should reconnect.</td></tr><tr><td>Node coordinates do not apply</td><td>PacketEvents must be installed and <code>advancement.packet-coordinates: true</code> must be enabled.</td></tr></tbody></table>`,18)])])}const u=d(n,[["render",s]]);export{h as __pageData,u as default};
